import openpyxl
template='mimotable_batch1_0267_template_4509_input.xlsx'
out='mimotable_batch1_0267_template_4509_input_filled.xlsx'
gold='/mnt/hhq/data/data_pipeline/corpus/mimotable_batch1/mimotable_batch1_0267.xlsx'
wbt=openpyxl.load_workbook(template)
wbo=openpyxl.load_workbook(out)
wbg=openpyxl.load_workbook(gold)
wst=wbt['基本数据']; wso=wbo['基本数据']; wsg=wbg['基本数据']
diffs=[]
for row in wst.iter_rows(min_row=2,max_row=20,min_col=1,max_col=18):
    for c in row:
        co=wso[c.coordinate]; ct=wst[c.coordinate]
        # compare style index, number format, fill, font, border, alignment, protection
        for attr in ['style_id','number_format']:
            a=getattr(ct,attr); b=getattr(co,attr)
            if a!=b: diffs.append((c.coordinate, attr, a,b))
        if ct.fill.fgColor.rgb != co.fill.fgColor.rgb or ct.fill.patternType != co.fill.patternType:
            diffs.append((c.coordinate,'fill', ct.fill.fgColor.rgb, co.fill.fgColor.rgb, ct.fill.patternType, co.fill.patternType))
        if ct.font.name!=co.font.name or ct.font.size!=co.font.size or ct.font.bold!=co.font.bold:
            diffs.append((c.coordinate,'font',ct.font.name,co.font.name,ct.font.size,co.font.size,ct.font.bold,co.font.bold))
        if ct.border.left.style!=co.border.left.style or ct.border.right.style!=co.border.right.style:
            diffs.append((c.coordinate,'border'))
print('style diffs', diffs[:20], 'count', len(diffs))
# also compare all formatting vs golden
diffs2=[]
for row in wsg.iter_rows(min_row=2,max_row=20,min_col=1,max_col=18):
    for c in row:
        co=wso[c.coordinate]; cg=wsg[c.coordinate]
        if cg.fill.fgColor.rgb != co.fill.fgColor.rgb or cg.fill.patternType != co.fill.patternType:
            diffs2.append((c.coordinate,'fill'))
        if cg.border.left.style!=co.border.left.style:
            diffs2.append((c.coordinate,'border'))
        if cg.number_format!=co.number_format:
            diffs2.append((c.coordinate,'nf',cg.number_format,co.number_format))
print('style diffs vs golden', diffs2[:20], 'count', len(diffs2))
